<?php
require __DIR__.'/includes/module.php';$u=require_auth();require_permission('customers.view');module_action('customers');$bid=(int)$u['business_id'];$pdo=db();$view=(int)($_GET['view']??0);$search=trim((string)($_GET['q']??''));$params=[$bid];$sql="SELECT c.*,COUNT(DISTINCT i.id) invoice_count,COALESCE(SUM(DISTINCT i.total),0) billed,COALESCE(SUM(DISTINCT i.amount_paid),0) received FROM customers c LEFT JOIN invoices i ON i.customer_id=c.id AND i.status<>'Void' WHERE c.business_id=? AND c.archived_at IS NULL";if($search!==''){$sql.=' AND (c.name LIKE ? OR c.company LIKE ? OR c.email LIKE ? OR c.phone LIKE ?)';array_push($params,...array_fill(0,4,'%'.$search.'%'));}$sql.=' GROUP BY c.id ORDER BY c.created_at DESC';$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();$item=null;if($view){$q=$pdo->prepare('SELECT * FROM customers WHERE id=? AND business_id=? AND archived_at IS NULL');$q->execute([$view,$bid]);$item=$q->fetch();if($item){$x=$pdo->prepare('SELECT invoice_number,invoice_date,total,amount_paid,status FROM invoices WHERE customer_id=? AND business_id=? ORDER BY invoice_date DESC');$x->execute([$view,$bid]);$item['invoices']=$x->fetchAll();}}$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM customers WHERE id=? AND business_id=?');$q->execute([(int)$_GET['edit'],$bid]);$edit=$q->fetch();}
$form=function($v=[]){return '<label>Name *<input required name="name" value="'.e($v['name']??'').'"></label><label>Company<input name="company" value="'.e($v['company']??'').'"></label><label>Email<input type="email" name="email" value="'.e($v['email']??'').'"></label><label>Phone<input name="phone" value="'.e($v['phone']??'').'"></label><label>GSTIN<input name="gstin" maxlength="15" value="'.e($v['gstin']??'').'"></label><label>State<input name="state" value="'.e($v['state']??'').'"></label><label>GST state code<input name="state_code" maxlength="2" pattern="[0-9]{2}" value="'.e($v['state_code']??'').'"></label><label>City<input name="city" value="'.e($v['city']??'').'"></label><label class="wide">Address<input name="address" value="'.e($v['address']??'').'"></label><label>Postal code<input name="postal_code" value="'.e($v['postal_code']??'').'"></label><label class="wide">Notes<textarea name="notes">'.e($v['notes']??'').'</textarea></label>';};
page_start($item?'Customer profile':'Customers','customers');module_css('customers');if($item):?>
<div class="section-head"><div><span class="eyebrow">CUSTOMER PROFILE</span><h1><?=e($item['name'])?></h1><p><?=e($item['company']?:'Customer')?> · Added <?=fmt_date($item['created_at'])?></p></div><button class="button primary" onclick="document.getElementById('record-modal').showModal()"><i class="ti ti-pencil"></i> Edit customer</button></div><div class="record-grid"><div class="content-card"><h2>Contact and tax details</h2><div class="detail-line"><span>Email</span><?=e($item['email']?:'—')?></div><div class="detail-line"><span>Phone</span><?=e($item['phone']?:'—')?></div><div class="detail-line"><span>Address</span><?=e($item['address']?:'—')?></div><div class="detail-line"><span>City / state</span><?=e(trim(($item['city']?:'').' '.($item['state']?:''))?:'—')?> <?=e($item['state_code']?'('.$item['state_code'].')':'')?></div><div class="detail-line"><span>GSTIN</span><?=e($item['gstin']?:'—')?></div><div class="detail-line"><span>Notes</span><?=nl2br(e($item['notes']?:'—'))?></div><h2 style="margin-top:22px">Invoice history</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>INVOICE</th><th>DATE</th><th>AMOUNT</th><th>STATUS</th></tr></thead><tbody><?php foreach($item['invoices'] as $inv):?><tr><td><?=e($inv['invoice_number'])?></td><td><?=fmt_date($inv['invoice_date'])?></td><td><?=money($inv['total'])?></td><td><?=e($inv['status'])?></td></tr><?php endforeach;if(!$item['invoices']):?><tr><td colspan="4" class="empty-row">No invoices yet.</td></tr><?php endif?></tbody></table></div></div><div class="content-card"><h2>Relationship summary</h2><div class="summary-tile"><small>Outstanding balance</small><strong><?php $balance=0;foreach($item['invoices'] as $i)if($i['status']!=='Void')$balance+=(float)$i['total']-(float)$i['amount_paid'];echo money($balance)?></strong></div><p class="help-text">Financial totals include non-void invoices and applied payments.</p><a class="button secondary" href="invoice-create.php?customer=<?=$view?>">Create invoice</a></div></div><?php modal_form('Edit customer','edit',$form($edit??[]));?><script>document.addEventListener('DOMContentLoaded',()=>document.getElementById('record-modal').showModal())</script><div style="margin-top:14px"><a class="subtle-link" href="customers.php">← All customers</a></div>
<?php else:section_head('RELATIONSHIPS','Customers','The people and businesses behind your work.','Add customer','#add');?><div class="content-card"><form class="toolbar"><input class="search" name="q" value="<?=e($search)?>" placeholder="Search name, company, email or phone"><button class="button secondary">Search</button><span class="help-text"><?=count($rows)?> customers</span></form><div class="table-scroll"><table class="data-table"><thead><tr><th>CUSTOMER</th><th>CONTACT</th><th>LOCATION</th><th>INVOICES</th><th>BILLED</th><th>OPEN BALANCE</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a class="table-strong" href="customers.php?view=<?=(int)$r['id']?>"><?=e($r['name'])?></a><div class="help-text"><?=e($r['company']?:'Individual')?></div></td><td><?=e($r['email']?:$r['phone']?:'—')?></td><td><?=e(trim(($r['city']?:'').' · '.($r['state']?:''))?:'—')?></td><td><?=$r['invoice_count']?></td><td><?=money($r['billed'])?></td><td><?=money((float)$r['billed']-(float)$r['received'])?></td><td><a class="link-button" href="customers.php?edit=<?=(int)$r['id']?>">Edit</a><form class="inline-form" method="post" onsubmit="return confirm('Archive this customer? Financial records remain available.')"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="link-button">Archive</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty-row">No customers yet. Add your first relationship to get started.</td></tr><?php endif?></tbody></table></div></div><?php modal_form('Add customer','create',$form());?><script>document.querySelector('a[href="#add"]').onclick=e=>{e.preventDefault();document.getElementById('record-modal').showModal()}</script><?php endif;page_end();
